function clamp(x,a,b){return Math.max(a,Math.min(b,x));}
function round(x){return Math.floor(x+.5);}
function wage(l){return V.pay_rounding*round(V.pay_base*V.pay_growth**(l-1)/V.pay_rounding);}
function contractPayout(level,factor=1,modifier=1){return round(V.normal_payout_base*(wage(level)/V.pay_base)*factor*modifier);}
function rank(l){return l>=17?'Legendary':l>=9?'Master':l>=5?'Expert':'Trained';}
function support(m,skill){return m.skills[skill]?V.support_by_rank[rank(m.level).toLowerCase()]:0;}
function skill(m,k){return m.skills[k]?V['skill_'+m.skills[k]][m.level]:2;}
function degree(face,mod,dc){let d=face+mod-dc;let n=d>=10?3:d>=0?2:d<=-10?0:1;return clamp(n+(face===20?1:face===1?-1:0),0,3);}
function die(seed,...keys){if(root.GuildmasterBridge)return root.GuildmasterBridge.die(seed,...keys);let h=2166136261;for(const c of JSON.stringify([seed,...keys])){h=Math.imul(h^c.charCodeAt(0),16777619);}h^=h>>>16;h=Math.imul(h,2246822507);h^=h>>>13;h=Math.imul(h,3266489909);h^=h>>>16;return (h>>>0)%20+1;}
function id(s,prefix){return prefix+(++s.serial);}
function log(s,title,text,kind='note'){s.log.unshift({turn:s.turn,title,text,kind});}
function money(s,amount,note,category){s.cash+=amount;s.ledger.push({turn:s.turn,amount,note,category});}
function error(text){throw new Error(text);}
function available(m){return m.status==='Available';}
function merc(s,mid){let m=s.mercs.find(x=>x.id===mid);if(!m)error('That operative is not in the roster.');return m;}
function offer(s,cid){let c=s.board.find(x=>x.id===cid);if(!c)error('That contract is no longer on the board.');return c;}
function officer(s,oid){let o=s.officers.find(x=>x.id===oid);if(!o)error('Choose an officer.');return o;}
function officerSkill(s,o,k){if(o.actorUuid)return o.skills[k]??0;const raw=o.skills[k]||2;return raw+(o.skills[k]&&!o.baseId?administrativeDC(s)-V.level_dc[1]:0);}
function administrativeDC(s){return V.level_dc[Math.min(20,2*s.guildLevel-1)];}
function checkFunds(s,cost){if(s.cash<cost)error('The treasury cannot fund that cost.');}
function checkAction(s,oid,cost=1){if(s.phase!=='activity')error('Finish Upkeep or the current event before taking Guild Actions.');const o=officer(s,oid),b=operating(s);if(!baseOperational(s,b))error('That base needs available, funded local management.');if(o.baseId){if(o.baseId!==b.id||o.readyAt>s.turn||base(s,o.baseId).chief?.paidTurn!==s.turn)error('The chief can act only at their funded outpost.');}else if(b.id!==s.primaryBase&&!localFacility(s,'comms_hub',s.primaryBase)&&!localFacility(s,'comms_hub',b.id))error('Use the local chief, or a staffed Comms Hub to lead remote administrative actions.');if(s.actions<cost)error('No shared Guild Actions remain.');return o;}

function spend(s,oid,label,cost=1,cashCost=0){const o=checkAction(s,oid,cost);checkFunds(s,cashCost);s.actions-=cost;o.used+=cost;if(cashCost)money(s,-cashCost,label,'management');s.actionHistory.push({turn:s.turn,officer:o.name,action:label,cost,credits:cashCost});}
function checkTrained(o,k){if(o.actorUuid?!(o.skillRanks?.[k]>0):!o.skills[k])error('This officer needs Trained '+k+'.');}
function rollAdmin(s,oid,label,k='Diplomacy',dc=administrativeDC(s)){const o=officer(s,oid);let native=root.GuildmasterBridge?.admin(s,o,label,k,dc);let face=native?.face??die(s.seed,'admin',s.turn,s.actionHistory.length,label);let mod=native?.modifier??officerSkill(s,o,k);let d=native?.degree??degree(face,mod,dc);s.lastRoll={label,officer:o.name,turn:s.turn,face,modifier:mod,total:face+mod,dc,degree:d};s.rollHistory=s.rollHistory||[];s.rollHistory.push({...s.lastRoll});log(s,label,`${o.name}: d20 ${face} +${mod} vs DC${dc}: ${names[d]}.`,'roll');return d;}
function xp(s,m,amount){m.xp+=amount;while(m.level<20&&m.xp>=1000){m.xp-=1000;m.level++;log(s,m.name+' reaches Level '+m.level,'Skill benchmarks and future wages increase. In-progress wage quotes stay fixed.','good');}}
function changeRep(s,n){s.reputation=clamp(s.reputation+n,-20,100);}
function changeLoyalty(s,m,n){m.loyalty=clamp(m.loyalty+n,0,100);if(m.loyalty===0&&!m.leaveAt){m.leaveAt=s.turn+1;log(s,m.name+' gives notice','They will become Inactive next boundary unless Loyalty is raised before then.','bad');}}
function makeMerc(s,template,level=1,ancestry=null){const mid='m'+(s.serial+1),state=s.contentState||{version:1,missionBag:[],recentMissions:[],ancestryBag:[]},bag=state.ancestryBag?.length?state.ancestryBag:C.ancestries.map(a=>a.id),selected=ancestry||bag[C.hash(s.seed,'ancestry-bag',mid)%bag.length],identity=C.identity(s.seed,mid,{ancestry:selected,usedNames:s.mercs.map(m=>m.name)});id(s,'m');s.contentState=state;if(!ancestry)state.ancestryBag=bag.filter(a=>a!==selected);return {id:mid,baseId:s.operatingBase||s.primaryBase||'hq',employment:'free',...JSON.parse(JSON.stringify(template)),...identity,level,xp:0,loyalty:50,status:'Available',leaderFeat:null};}
function initializeContent(s){if(!s.contentState)s.contentState={version:1,missionBag:[],recentMissions:[]};return s.contentState;}
function addOffer(s,key,level=1,extra={}){let template=templates.find(x=>x.key===key),typeId=C.legacyAliases[key],draw=null;const state=s.contentState||{version:1,missionBag:[],recentMissions:[]},cid='c'+(s.serial+1);if(key==='generated'){draw=C.drawMission(state.missionBag,s.seed,[cid,extra.profileRoll??null],state.recentMissions);typeId=draw.type.id;template={key:typeId,kind:extra.kind||'standard'};}else if(C.missionTypes.some(t=>t.id===key)){typeId=key;template={key,kind:extra.kind||'standard'};}if(!typeId||!template||!V.contracts[extra.kind||template.kind])error('Choose a supported contract template and risk profile.');const content=C.mission(s.seed,cid,typeId,{client:extra.client||template.client,usedNames:s.board.map(c=>c.name)}),c={...JSON.parse(JSON.stringify(template)),...content,baseId:s.operatingBase||s.primaryBase||'hq',id:cid,level,status:'Offer',expires:s.turn+1,...extra};if(template.skills)c.skills=[...template.skills];id(s,'c');s.contentState=state;if(draw){state.missionBag=draw.remaining;state.recentMissions=[...state.recentMissions,typeId].slice(-3);}s.board.push(c);return c;}
function actionPool(s){return s.partySize+s.guildLevel-1;}
function partyOfficers(count){const profiles=[{id:'command',name:'Navasi',role:'Human Envoy · Commander',skills:{Diplomacy:10,Performance:10,Piloting:10,Survival:10}},{id:'quarter',name:'Iseph',role:'Android Operative · Quartermaster',skills:{Diplomacy:10,Computers:10,Crafting:10,Medicine:10,Society:10}},{id:'field',name:'Dae',role:'Pahtra Solarian · Field Operations',skills:{Athletics:10,Stealth:10,Survival:10,Medicine:10}},{id:'liaison',name:'Chk Chk',role:'Shirren Mystic · Personnel & Medical',skills:{Diplomacy:10,Medicine:10,Occultism:10,Survival:10}}];return Array.from({length:count},(_,i)=>({...JSON.parse(JSON.stringify(profiles[i%4])),id:i<4?profiles[i].id:'pc'+(i+1),name:i<4?profiles[i].name:'PC '+(i+1),used:0,heroPoints:V.hero_points.per_session}));}

function base(s,bid=s.operatingBase||s.primaryBase){const b=s.bases.find(x=>x.id===bid);if(!b)error('Choose an existing base.');return b;}
function baseOperational(s,b){return b.status==='Operational'&&(b.type!=='outpost'||(b.chief&&b.chief.readyAt<=s.turn&&b.chief.paidTurn===s.turn));}
function operating(s){return base(s);}
function localMercs(s){return s.mercs.filter(m=>(m.baseId||s.primaryBase)===(s.operatingBase||s.primaryBase));}
function facilityOperational(s,f){return f.condition==='Operational'&&!f.transfer&&f.staff?.active&&f.staff.paidTurn===s.turn&&baseOperational(s,base(s,f.baseId));}
function localFacility(s,type,bid=s.operatingBase||s.primaryBase){return s.facilities.find(f=>f.type===type&&f.baseId===bid&&facilityOperational(s,f));}
function locationSlots(s,bid){const b=base(s,bid),installed=s.facilities.filter(f=>f.baseId===bid).length,projects=s.projects.filter(p=>!p.done&&!p.repairId&&p.baseId===bid).length,transfers=s.facilities.filter(f=>f.transfer?.to===bid).length;return {total:b.slots,used:installed,reserved:projects+transfers,free:b.slots-installed-projects-transfers};}
function focusBase(s,bid){const b=base(s,bid);if(b.status!=='Operational')error('That location is not available.');s.operatingBase=bid;}
function newFacility(s,type,bid,landlordOwned=false){const v=V.facilities[type];return {id:id(s,'f'),type,baseId:bid,condition:'Operational',activeSince:s.turn,landlordOwned,staff:{name:v.staff_name,monthly:v.staff_monthly,active:true,paidTurn:0}};}
function staffDue(s,f){return !!f.staff?.active&&!f.transfer&&base(s,f.baseId).status==='Operational';}
function assignmentWage(m){return m.employment==='retained'?5*Math.ceil(wage(m.level)*.8/5):wage(m.level);}
function retainer(m){return m.employment==='retained'?5*Math.ceil(wage(m.level)*.5/5):0;}
function ensureFundedMercs(s,members){if(members.some(m=>m.employment==='retained'&&m.retainerPaidTurn!==s.turn))error('Fund the retained operative’s current retainer before assigning work.');}
function forecast(s,turn=s.turn+1){let total=0;for(const b of s.bases)if(b.status!=='Closed'&&b.readyAt<=turn&&(!b.endsAt||b.endsAt>turn)){total+=b.monthly;if(b.chief&&b.chief.readyAt<=turn)total+=b.chief.monthly;}for(const f of s.facilities){if(f.activeSince<turn&&(!f.returnedAt||f.returnedAt===turn)&&(!f.landlordOwned||!base(s,f.baseId).endsAt||base(s,f.baseId).endsAt>=turn))total+=V.facilities[f.type].monthly;if(f.staff?.active&&(!f.transfer||f.transfer.due<=turn))total+=f.staff.monthly;}for(const p of s.projects)if(!p.done&&!p.repairId&&p.due<=turn){total+=V.facilities[p.type].staff_monthly;if(p.due<turn)total+=V.facilities[p.type].monthly;}for(const m of s.mercs)if(m.employment==='retained'&&!['Candidate','Expired','Inactive','Dead','Released'].includes(m.status)&&(!m.readyAt||m.status!=='Onboarding'||m.readyAt<=turn))total+=retainer(m);for(const l of s.loans||[])total+=loanDue(s,l,turn).total;return total;}
function addInvoice(s,key,label,amount,type,reference=null,baseId=null){s.upkeep.invoice.push({id:`T${s.turn}:${key}`,label,amount,paid:0,type,reference,baseId});}
function prepareUpkeep(s){if(s.upkeep.prepared)return;s.upkeep.prepared=true;s.upkeep.invoice=[];s.upkeep.changes=[];s.upkeep.cashBefore=s.cash;
 for(const b of s.bases){if(b.status==='Pending'&&b.readyAt<=s.turn){b.status='Operational';s.upkeep.changes.push(b.name+' is available.');}if(b.endsAt&&b.endsAt<=s.turn){b.status='Closed';for(const f of s.facilities)if(f.baseId===b.id&&f.landlordOwned&&!f.returnedAt)f.returnedAt=s.turn;s.upkeep.changes.push(b.name+' lease ended.');}}
 for(const f of s.facilities)if(f.transfer&&f.transfer.due<=s.turn){f.baseId=f.transfer.to;delete f.transfer;s.upkeep.changes.push(V.facilities[f.type].name+' transfer completed.');}
 for(const c of s.cohorts)if(c.active&&c.due<=s.turn&&!c.waiting){let award=c.intensive?V.advanced_actions.intensive.xp:Math.floor(150*(1+Math.min(.1*(c.block-1),.5))+1e-8);c.ids.forEach(i=>xp(s,merc(s,i),award));c.waiting=!c.intensive;s.metrics.trainingBlocks++;if(c.intensive){c.active=false;c.ids.forEach(i=>merc(s,i).status='Available');}else s.upkeep.choices.push({id:id(s,'u'),type:'training',cohort:c.id});s.upkeep.changes.push(`Training block ${c.block}: ${award} XP each.`);}
 for(const p of s.projects)if(!p.done&&p.due<=s.turn){p.done=true;if(p.repairId){s.facilities.find(f=>f.id===p.repairId).condition='Operational';}else{const f=newFacility(s,p.type,p.baseId);s.facilities.push(f);}s.upkeep.changes.push(V.facilities[p.type].name+' is installed; staffing must be funded.');}
 for(const a of s.arrears)if(a.amount>0)addInvoice(s,'arrears:'+a.id,'Prior arrears: '+a.creditor,a.amount,'arrears',a.id);
 for(const b of s.bases)if(b.status==='Operational'){addInvoice(s,'base:'+b.id,b.name+' · '+(b.type==='leased_station_hq'?'250 rent + 50 routine services':'property upkeep'),b.monthly,'base',b.id,b.id);if(b.chief&&b.chief.readyAt<=s.turn)addInvoice(s,'chief:'+b.id,b.chief.name+' · Outpost Chief',b.chief.monthly,'chief',b.id,b.id);}
 for(const f of s.facilities){const v=V.facilities[f.type];if(f.activeSince<s.turn&&(!f.returnedAt||f.returnedAt===s.turn)){let amount=v.monthly;if(f.saving?.turn===s.turn)amount-=Math.floor(amount*f.saving.rate);addInvoice(s,'asset:'+f.id,v.name+' · prior interval maintenance',amount,'asset',f.id,f.baseId);}if(staffDue(s,f))addInvoice(s,'staff:'+f.id,f.staff.name+' · current interval service',f.staff.monthly,'staff',f.id,f.baseId);}
 for(const m of s.mercs)if(m.employment==='retained'&&!['Candidate','Expired','Inactive','Dead','Released','Onboarding'].includes(m.status))addInvoice(s,'retainer:'+m.id,m.name+' · retainer',retainer(m),'retainer',m.id,m.baseId);
 loanInvoice(s);
 log(s,'Upkeep ready for review',`${s.upkeep.invoice.reduce((n,l)=>n+l.amount,0)} credits due. Review staffing and obligations before payment; no Guild Action is spent.`);
}
function paidService(s,line){if(line.type==='base')base(s,line.reference).paidTurn=s.turn;if(line.type==='staff'){const f=s.facilities.find(f=>f.id===line.reference);if(f)f.staff.paidTurn=s.turn;}if(line.type==='chief'){const b=base(s,line.reference);b.chief.paidTurn=s.turn;b.milestone=true;}if(line.type==='retainer')merc(s,line.reference).retainerPaidTurn=s.turn;claimMilestones(s);}
function payInvoiceLine(s,lid){if(s.phase!=='upkeep'||s.upkeep.settled)error('Review payments during an unsettled Upkeep.');const line=s.upkeep.invoice.find(l=>l.id===lid);if(!line||line.paid>=line.amount)error('That invoice line is already settled.');let amount=Math.min(s.cash,line.amount-line.paid);if(!amount)error('No cash is available for this obligation.');if(line.type==='loan')applyLoanPayment(s,line,amount);money(s,-amount,line.label,line.type==='base'?'rent':line.type==='asset'?'facility':line.type);line.paid+=amount;if(line.type==='arrears'){let a=s.arrears.find(a=>a.id===line.reference);if(a.service?.type==='loan'){applyLoanPayment(s,a.service,amount);a.service.paid+=amount;}a.amount-=amount;if(a.amount===0&&a.service&&a.turn===s.turn)paidService(s,a.service);}if(line.paid===line.amount)paidService(s,line);}
function settleUpkeep(s){if(s.phase!=='upkeep')error('Settle payments during Upkeep.');if(s.upkeep.settled)error('This Upkeep invoice is already settled.');const paymentOrder=[...s.upkeep.invoice.filter(l=>l.type!=='arrears'),...s.upkeep.invoice.filter(l=>l.type==='arrears')];for(const line of paymentOrder)if(line.paid<line.amount&&s.cash>0)payInvoiceLine(s,line.id);for(const line of s.upkeep.invoice)if(line.type!=='arrears'&&line.paid<line.amount){const due=line.amount-line.paid;s.arrears.push({id:id(s,'a'),creditor:line.label,amount:due,type:line.type,turn:s.turn,service:{...line}});log(s,'Unpaid obligation',`${line.label}: ${due} owed. Unfunded staff and retainers provide no current service. No automatic eviction, termination or Loyalty change in this prototype.`,'bad');}s.arrears=s.arrears.filter(a=>a.amount>0);for(const l of s.loans||[])refreshLoan(s,l);s.upkeep.settled=true;s.upkeep.cashAfter=s.cash;log(s,'Upkeep payments recorded',`${s.upkeep.invoice.reduce((n,l)=>n+l.paid,0)} actually paid; ${s.arrears.reduce((n,a)=>n+a.amount,0)} total arrears. Optional training comes after mandatory payments.`);}
function renewStaff(s,fid,active){if(s.phase!=='upkeep'||s.upkeep.settled)error('Renew services before settling Upkeep.');const f=s.facilities.find(f=>f.id===fid);if(!f||f.transfer)error('That facility cannot renew here.');if(!!active===f.staff.active)error('That renewal choice is already recorded.');const line=s.upkeep.invoice.find(l=>l.id===`T${s.turn}:staff:${fid}`);if(line?.paid)error('A paid service cannot be retroactively cancelled.');f.staff.active=!!active;s.upkeep.invoice=s.upkeep.invoice.filter(l=>l!==line);if(active)addInvoice(s,'staff:'+f.id,f.staff.name+' · current interval service',f.staff.monthly,'staff',f.id,f.baseId);log(s,active?'Facility service renewed':'Facility service paused',V.facilities[f.type].name+': month-to-month support contract. Accrued asset costs remain owed.');}
function purchaseBase(s,type,oid){if(s.guildLevel<V.development_unlocks.properties)error('New bases unlock at Guild Level 4.');const v=V.base_market[type];if(!v)error('Choose an offered property.');spend(s,oid,'Negotiate Property Deal: '+v.name,1,v.purchase_price);const b={id:id(s,'b'),type,name:v.name+' '+s.serial,region:type==='outpost'?'Meridian outer docks':'Station Meridian',status:'Pending',readyAt:s.turn+1,slots:v.slots,monthly:v.property_monthly,chief:null,milestone:false};s.bases.push(b);log(s,'Property purchased',`${b.name}: ${v.purchase_price} paid, empty turnkey property. Available Turn ${b.readyAt}; ${b.monthly}/month from possession. No construction manager or second purchase action.`, 'good');return b;}
function appointChief(s,bid,oid){const b=base(s,bid);if(b.type!=='outpost'||b.chief)error('Choose an outpost without a chief.');spend(s,oid,'Appoint Officer: '+b.name,1,100);b.chief={id:'chief-'+b.id,name:'Chief '+b.id.slice(1),level:1,role:'Outpost Chief · '+b.name,baseId:b.id,monthly:125,readyAt:s.turn+1,paidTurn:0,used:0,skills:{Diplomacy:7,Society:7,Computers:7}};s.officers.push(b.chief);log(s,'Outpost chief hired',`${b.name}: 100 hiring, 125/month from Turn ${b.chief.readyAt}. Uses the existing shared pool; no new actions.`, 'good');}
function relocate(s,bid,oid,moveFacilities=true){const target=base(s,bid),origin=base(s,s.primaryBase);if((s.loans||[]).some(l=>l.status==='Default'&&[origin.id,target.id].includes(l.collateral)))error('Resolve the pledged property’s default before relocation.');if(target.id===origin.id||target.status!=='Operational'||target.type==='outpost')error('Choose an available owned HQ destination.');const moving=moveFacilities?s.facilities.filter(f=>f.baseId===origin.id&&!f.landlordOwned):[];if(moving.some(f=>f.transfer))error('A selected asset is already transferring.');if(s.cohorts.some(c=>c.active&&(c.baseId||origin.id)===origin.id))error('Release active training cohorts before moving headquarters.');if(s.mercs.some(m=>(m.baseId||origin.id)===origin.id&&['Deployed','Recovering','In Transit','Onboarding'].includes(m.status)))error('Wait for personnel commitments to finish before relocating headquarters.');if(s.projects.some(p=>!p.done&&p.baseId===origin.id))error('Finish construction at the origin first.');if(moving.some(f=>s.facilities.some(t=>t.baseId===target.id&&t.type===f.type)||s.projects.some(p=>!p.done&&p.baseId===target.id&&p.type===f.type)))error('The destination already has or is building a matching installation.');if(locationSlots(s,target.id).free<moving.length)error('The destination cannot fit the selected upgrades.');const turns=Math.max(1,...moving.map(f=>V.facilities[f.type].transferable));const cost=moving.reduce((n,f)=>n+round(V.facilities[f.type].cost*.1),0)+100*turns;spend(s,oid,'Relocate Operations',1,cost);s.primaryBase=target.id;s.operatingBase=target.id;for(const m of s.mercs)if(m.baseId===origin.id&&m.status==='Available'){m.baseId=target.id;m.status='In Transit';m.readyAt=s.turn+1;}for(const f of moving)f.transfer={to:target.id,due:s.turn+V.facilities[f.type].transferable};if(origin.type==='leased_station_hq')origin.endsAt=s.turn+turns;for(const f of s.facilities)if(f.baseId===origin.id&&f.landlordOwned)f.staff.active=false;target.milestone=true;claimMilestones(s);log(s,'Relocation funded',`${cost} includes move manager. Personnel arrive next Upkeep; ${moving.length} owned installation(s) transfer on their printed clocks. ${origin.type==='leased_station_hq'?'Old lease ends Turn '+origin.endsAt+'.':'Origin ownership costs continue.'} Existing paid rent is not refunded.`, 'good');}
function transferCrew(s,ids,bid,oid){const target=base(s,bid),origin=operating(s);if(!baseOperational(s,target)||target.id===origin.id)error('Choose another operational base.');if(!ids.length||new Set(ids).size!==ids.length)error('Choose unique crew to transfer.');const members=ids.map(i=>merc(s,i));if(members.some(m=>!available(m)||m.baseId!==origin.id))error('Transfer Available local operatives only.');ensureFundedMercs(s,members);spend(s,oid,'Transfer Personnel',1,25*ids.length);for(const m of members){m.status='In Transit';m.baseId=target.id;m.readyAt=s.turn+1;}log(s,'Personnel transfer',`${members.length} operatives, ${25*ids.length} local transport credits. Available at ${target.name} next Upkeep; no same-turn assignment.`);}


function contractRule(c){return c.rulesSnapshot||V.contracts[c.kind];}
function rankIndex(r){return ['Untrained','Trained','Expert','Master','Legendary'].indexOf(r);}
function leadRank(m,k){return m.skills[k]?rank(m.level):'Untrained';}
function leadEligible(c,m,p){return rankIndex(leadRank(m,c.skills[p]))>=rankIndex(c.minimumLeadRanks?.[p]||contractRule(c).minimum_lead_rank||'Untrained');}
function chooseLeads(s,c,ids){let best=null,bestScore=-Infinity;function choose(p,used,score){if(p===3){if(score>bestScore){best=[...used];bestScore=score;}return;}for(const i of ids)if(!used.includes(i)&&leadEligible(c,merc(s,i),p))choose(p+1,[...used,i],score+skill(merc(s,i),c.skills[p]));}choose(0,[],0);return best;}
function consequencePreview(c){const r=contractRule(c);if(!r.complication_trigger)return 'Legacy contract: previously quoted consequences are preserved.';return `${r.complication_trigger==='critical_failure'?'Critical Failure only':'Failure or Critical Failure'}: Insertion can require ${r.severity} recovery turn(s) for its lead; Engagement damages charter transport (${round(wage(c.level)*r.severity*(r.complication_trigger==='critical_failure'?.5:1))} repair credits, doubled on a triggering Critical Failure for risky tiers); Extraction can leave its lead Missing until a rescue. ${r.additional_reward?'Completion also unlocks a specialist referral'+(r.additional_reward==='recruit_and_contact'?' and a new client contact':'')+'.':''}`;}
function phaseComplication(s,j,p,d){const card=j.quote.contractRules||j.rulesSnapshot||contractRule(j.contract);if(!card.complication_trigger||d>=2||(card.complication_trigger==='critical_failure'&&d!==0))return null;const severity=(card.severity||1)*(d===0&&card.complication_trigger==='failure'?2:1);let outcome;if(p===0)outcome={type:'injury',lead:j.leads[p],recovery:severity,text:`${merc(s,j.leads[p]).name}: ${severity} recovery turn(s) on return.`};else if(p===1){const amount=round((j.quote.repairWage??j.repairWageSnapshot??wage(j.contract.level))*severity*(card.complication_trigger==='critical_failure'?.5:1));outcome={type:'repairs',amount,text:`Charter transport damaged: ${amount} repair credits due in Events. No owned starship is assumed.`};}else outcome={type:'missing',lead:j.leads[p],text:`${merc(s,j.leads[p]).name} fails to return and is Missing; unavailable until a rescue adventure. No automatic death.`};outcome.phase=p;outcome.degree=d;return outcome;}
function heroPCs(s){return s.officers.filter(o=>!o.baseId);}
function awardHeroPoint(s,oid){const o=officer(s,oid);if(o.baseId)error('Hero Points belong to PCs, not hired chiefs.');if(o.heroPoints>=V.hero_points.maximum)error('This PC already has the maximum Hero Points.');o.heroPoints++;log(s,'Hero Point awarded',o.name+' now has '+o.heroPoints+'. GM/table award; no Guild Action.','good');}
function startHeroSession(s){if(s.operations?.pendingReview)error('Accept the pending phase before starting a new table session.');s.heroSession=(s.heroSession||1)+1;heroPCs(s).forEach(o=>o.heroPoints=V.hero_points.per_session);log(s,'New table session',`Session ${s.heroSession}: each PC begins with ${V.hero_points.per_session} Hero Point; previous session points expire. This is not a Guild Turn reset.`);}
function rerollPhase(s,oid){if(s.phase!=='event'||!s.operations?.pendingReview||s.operations.settled)error('Spend a Hero Point before accepting the pending mission phase.');const pending=s.operations.pendingReview,j=s.jobs.find(j=>j.id===pending.job),p=pending.phase,r=j?.rolls[p];if(!r||p!==j.rolls.length-1)error('Only the most recent unaccepted phase can be rerolled.');if(r.heroSpent)error('Only one Hero Point can be spent on this check.');const o=officer(s,oid);if(o.baseId||!Number.isInteger(o.heroPoints)||o.heroPoints<1)error('Choose a PC with a Hero Point.');const original={face:r.face,degree:r.degree,total:r.face+r.actualModifier,complication:r.complication},face=die(s.seed,'mission-hero',j.departure,j.contract.id,p),d=degree(face,r.actualModifier,r.dc);o.heroPoints--;r.originalRoll=original;r.heroSpent={id:o.id,name:o.name,session:s.heroSession};r.face=face;r.total=face+r.actualModifier;r.degree=d;r.complication=phaseComplication(s,j,p,d);log(s,j.contract.name+' · Hero Point reroll',`${o.name} spent 1: ${phases[p]} original d20 ${original.face} (${names[original.degree]}) → d20 ${face} +${r.actualModifier} =${r.total} vs DC${r.dc}: ${names[d]}. Second result kept; review before continuing.`,'roll');return r;}

function acknowledgePhase(s){if(s.phase!=='event'||!s.operations?.pendingReview)error('No phase result awaits review.');const pending=s.operations.pendingReview;s.operations.pendingReview=null;const j=s.jobs.find(j=>j.id===pending.job);if(j.rolls.length===3&&!nextJob(s))settleOperations(s);}

function fresh(seed=7,free=false,partySize=4,preset='staffed'){if(!Number.isInteger(partySize)||partySize<1||partySize>8)error('Choose 1–8 PCs for this demo.');let s={schema:'contract-operations-browser-1',rules:'0.3.11',heroSession:1,seed:Number.isInteger(Number(seed))?Number(seed):7,freeAcquisition:!!free,turn:1,phase:'upkeep',serial:0,cash:2000,partySize,actions:0,guildLevel:1,guildXP:0,pendingGuildXP:0,featChoices:0,guildFeats:[],contacts:['Helix Transit','Station Authority'],reputation:0,relations:2,mercs:[],board:[],jobs:[],cohorts:[],projects:[],facilities:[],loans:[],arrears:[],actionHistory:[],ledger:[],log:[],feedback:'',metrics:{completed:0,failed:0,trainingBlocks:0,hires:0},trustedUsed:false,pipelineUsed:false,searches:0,upkeep:{settled:false,choices:[],complete:false},operations:null,event:null,lastRoll:null};if(!['lean','staffed','developing','expansion'].includes(preset))error('Choose a known setup preset.');s.preset=preset;s.initialCash=preset==='expansion'?8000:2000;s.cash=s.initialCash;s.bases=[{id:'hq',type:'leased_station_hq',name:'Station Operations Office',region:'Station Meridian',status:'Operational',readyAt:1,slots:2,monthly:300,chief:null,milestone:true}];s.primaryBase='hq';s.operatingBase='hq';s.officers=partyOfficers(partySize);if(preset==='developing')s.guildLevel=2;if(preset==='expansion'){s.guildLevel=4;s.reputation=20;s.featChoices=1;}for(let i=0;i<4;i++){const m=makeMerc(s,people[i],preset==='expansion'?3:1);m.callSign=people[i].name;s.mercs.push(m);}for(const m of s.mercs){m.baseId='hq';m.employment='free';}addOffer(s,'escort',preset==='expansion'?3:1);addOffer(s,'relay',preset==='expansion'?3:1);if(preset==='expansion'){addOffer(s,'cargo',3);addOffer(s,'breach',3);addOffer(s,'expert',3);addOffer(s,'legendary',3);}if(preset==='staffed')s.facilities.push(newFacility(s,'training_suite','hq',true));initializeMilestones(s);log(s,'Open for business',`Setup: ${preset}. ${s.initialCash} credits; four operatives and ${partySize} PCs. Review the first current-interval Upkeep invoice before opening Activity. Expansion is an artificial mid-campaign fixture.`, 'good');prepareUpkeep(s);return s;}

function quote(s,c,ids,leads,leader=null){if(ids.length<3||ids.length>6)error('This card requires three to six operatives, with one different lead for each phase.');if(new Set(ids).size!==ids.length)error('An operative cannot occupy two squad slots.');let squad=ids.map(i=>merc(s,i));ensureFundedMercs(s,squad);if(!baseOperational(s,operating(s)))error('Fund local management before deployment.');if(c.baseId&&c.baseId!==operating(s).id)error('Deploy this contract from its origin base.');if(squad.some(m=>!available(m)||m.baseId!==operating(s).id||m.dispatchedTurn===s.turn))error('Every selected operative must be Available and not already assigned a new job this turn.');let average=Math.floor(squad.reduce((a,m)=>a+m.level,0)/ids.length);let minimum=Math.max(1,c.level-2);if(average<minimum)error(`This card needs minimum Squad Level ${minimum}; this squad averages ${average}.`);if(!Array.isArray(leads)||leads.length!==3||leads.some(l=>!ids.includes(l))||new Set(leads).size!==3)error('Declare three different squad members as phase leads; each operative can lead only one check.');if(leads.some((i,p)=>!leadEligible(c,merc(s,i),p)))error('A selected lead does not meet its phase’s listed skill proficiency.');if(leader){const l=merc(s,leader);if(!ids.includes(leader)||l.level<5||!l.leaderFeat)error('Choose a Level 5+ squad member with a chosen Leader Feat.');}let modifier=clamp(1-.1*Math.max(0,ids.length-4)-.1*Math.max(0,average-c.level),.5,1);let card=contractRule(c);let payout=contractPayout(c.level,card.payout_factor,modifier);let pay=squad.reduce((a,m)=>a+assignmentWage(m),0);let sizeBonus=Math.max(0,ids.length-4);let dc=V.level_dc[c.level]+card.dc_offset+Math.min(2,Math.max(0,4-ids.length));const cap=s.guildFeats.includes('provisioned')?4:3;let prepared=c.preparation&&c.preparation.expires>=s.turn?c.preparation:null;for(const plan of [prepared,c.contingency?.expires>=s.turn?c.contingency:null])if(plan?.lock){const lock=plan.lock;if(JSON.stringify([...ids].sort())!==JSON.stringify([...lock.ids].sort())||JSON.stringify(leads)!==JSON.stringify(lock.leads)||(leader||null)!==(lock.leader||null))error('This operation plan locks its squad, three leads and leader.');}let leaderFeat=leader?merc(s,leader).leaderFeat:null;let checks=c.skills.map((k,p)=>{let lead=merc(s,leads[p]);let helpers=squad.filter(m=>m.id!==lead.id&&m.skills[k]);let raw=helpers.reduce((a,m)=>a+support(m,k),0);let b=Math.min(cap,raw);let feat=(leaderFeat==='breach'&&p===1&&k==='Athletics')||(leaderFeat==='ghost'&&p===0&&k==='Stealth')||(leaderFeat==='systems'&&p===1&&k==='Computers')||(leaderFeat==='navigator'&&p===2&&k==='Survival')?1:0;let prep=prepared&&(prepared.allPhases||prepared.phase===p)?prepared.bonus:0;let circumstance=Math.max(sizeBonus,feat,prep)+Math.min(0,prep);return {phase:phases[p],skill:k,lead:lead.id,leadName:lead.name,skillBonus:skill(lead,k),support:b,supporters:helpers.map(m=>({id:m.id,name:m.name,rank:rank(m.level),contribution:support(m,k),marginal:Math.min(cap,raw)-Math.min(cap,raw-support(m,k))})),circumstance,modifier:skill(lead,k)+b+circumstance,dc};});return {guildAward:contractThreat(s,c),contingency:c.contingency?.expires>=s.turn?JSON.parse(JSON.stringify(c.contingency)):null,repairWage:wage(c.level),contractRules:JSON.parse(JSON.stringify(card)),squadLevel:average,minimum,sizeBonus,modifier,payout,pay,checks,leaderFeat,wageQuotes:squad.map(m=>({id:m.id,name:m.name,level:m.level,wage:assignmentWage(m),employment:m.employment}))};}
function acquisitionCost(s,c,useFeat=false){const eligible=c.kind==='standard'&&s.contacts.includes(c.client)&&(s.guildFeats.includes('trusted')||s.guildFeats.includes('standing'));const requested=!!useFeat||!!c.standing;if(useFeat&&(!eligible||s.trustedUsed))error('No eligible acquisition waiver is available for this card.');const waiver=requested&&eligible&&!s.trustedUsed;return {cost:s.freeAcquisition||waiver?0:1,waiver};}
function secure(s,cid,oid,useFeat=false){const c=offer(s,cid);if(c.baseId!==operating(s).id)error('Secure contracts at their origin base.');if(c.status!=='Offer'||c.expires<s.turn)error('That offer has expired or is already accepted.');const q=acquisitionCost(s,c,useFeat);spend(s,oid,'Secure Contract: '+c.name,q.cost);if(q.waiver)s.trustedUsed=true;c.status='Accepted';c.acceptedTurn=s.turn;c.deployBy=c.kind==='exclusive'?s.turn:s.turn+1;log(s,'Contract secured',`${c.name}. ${q.cost?'One Guild Action spent.':'Acquisition is free.'} ${q.waiver?'The shared Trusted/Standing allowance is used. ':''}Deployment is routine; it still requires Available crew.`,'good');}
function deploy(s,cid,ids,leads,leader=null){if(s.phase!=='activity')error('Deploy during Activity.');let c=offer(s,cid);if(c.status!=='Accepted')error('Secure this contract before deploying.');if(c.deployBy<s.turn)error('Its deployment window has closed.');let q=quote(s,c,ids,leads,leader);let j={id:id(s,'j'),contract:JSON.parse(JSON.stringify(c)),baseId:operating(s).id,departure:s.turn,due:s.turn,ids:[...ids],leads:[...leads],leader,quote:q,rolls:[],settled:false};s.jobs.push(j);c.status='Deployed';ids.forEach(i=>{const m=merc(s,i);m.status='Deployed';m.dispatchedTurn=s.turn;});log(s,'Squad deployed',`${c.name}; Squad Level ${q.squadLevel}. Frozen wages ${q.pay}; client payout ${q.payout} only on completion. No deployment action.`,'good');return j;}
function discoveryEntry(d,level,rolls,cap){const t=V.discovery,pick=(table,face)=>table[d].find(row=>face<=row[0])[1];return {level:clamp(level+pick(t.level_offsets,rolls.level),1,cap),kind:pick(t.difficulty,rolls.difficulty),rarity:pick(t.rarity,rolls.rarity)};}
function network(s,oid,mode='recruits',level=1,ancestry=null){if(ancestry&&!C.ancestries.some(a=>a.id===ancestry))error('Choose a supported ancestry.');level=Number(level);const cap=Math.min(20,2*s.guildLevel+1);if(!Number.isInteger(level)||level<1||level>cap)error('Choose a search level available to this guild.');if(!['recruits','contracts'].includes(mode))error('Choose a network search mode.');spend(s,oid,'Work the Network: '+mode);const d=rollAdmin(s,oid,'Network '+mode,'Diplomacy',V.level_dc[level]);s.searches++;const countRoll=d===0?die(s.seed,'discovery-count',s.turn,s.searches,mode):null,count=d===0?(countRoll<=V.discovery.critical_failure_count_roll.zero_through?0:1):V.discovery.default_count,results=[];const pipeline=mode==='recruits'&&d>0&&s.guildFeats.includes('pipeline')&&!s.pipelineUsed;let office=mode==='recruits'&&d>=2&&!!localFacility(s,'recruitment_office'),officeUsed=false;for(let n=0;n<count;n++){const rolls={level:die(s.seed,'discovery-level',s.turn,s.searches,mode,n),difficulty:die(s.seed,'discovery-difficulty',s.turn,s.searches,mode,n),rarity:die(s.seed,'discovery-rarity',s.turn,s.searches,mode,n),profile:die(s.seed,'discovery-profile',s.turn,s.searches,mode,n)};const entry=discoveryEntry(d,level,rolls,cap),notes=[];if(mode==='recruits'){if(pipeline&&n===0){entry.level=Math.min(cap,entry.level+1);s.pipelineUsed=true;notes.push('Recruitment Pipeline +1 level');}if(office&&!officeUsed&&entry.rarity==='Common'){entry.rarity='Uncommon';officeUsed=true;notes.push('Recruitment Office specialist');}const m=makeMerc(s,people[(rolls.profile-1)%people.length],entry.level,ancestry);m.status='Candidate';m.expires=s.turn+1;m.rarity=entry.rarity;const extra=V.discovery.candidate_skill_by_rarity[m.rarity];if(extra){const unlisted=['Diplomacy','Computers','Crafting','Medicine','Society','Stealth','Survival','Athletics','Piloting','Occultism','Deception','Intimidation','Nature','Thievery'].filter(k=>!m.skills[k]),extraRoll=die(s.seed,'discovery-skill',s.turn,s.searches,n);rolls.skill=extraRoll;const k=unlisted[(extraRoll-1)%unlisted.length];m.skills[k]=extra;notes.push(`${k} ${extra} specialist skill`);m.bio+=' Specialist referral with additional '+k+' training.';}s.mercs.push(m);results.push({id:m.id,name:m.name,ancestry:m.ancestry,callSign:m.callSign,level:m.level,rarity:m.rarity,rolls,notes});}else{const c=addOffer(s,'generated',entry.level,{kind:entry.kind,rarity:entry.rarity,profileRoll:rolls.profile});results.push({id:c.id,name:c.name,level:c.level,kind:c.kind,category:c.category,archetype:c.archetype,rarity:c.rarity,rolls,notes});}}s.lastDiscovery={turn:s.turn,mode,degree:d,targetLevel:level,countRoll,results};s.discoveryHistory=s.discoveryHistory||[];s.discoveryHistory.push(JSON.parse(JSON.stringify(s.lastDiscovery)));log(s,'Network results',`${names[d]}: ${count} ${mode==='recruits'?'candidates':'leads'}${countRoll!==null?' (quantity d20 '+countRoll+')':''}. `+results.map(x=>`${x.name}: L${x.level}, ${x.kind?V.contracts[x.kind].label+', ':''}${x.rarity}; table dice level ${x.rolls.level}${mode==='contracts'?', difficulty '+x.rolls.difficulty:''}, rarity ${x.rolls.rarity}, profile ${x.rolls.profile}${x.rolls.skill?', skill '+x.rolls.skill:''}${x.notes.length?' · '+x.notes.join(', '):''}`).join('; ')+`. Expires end Turn ${s.turn+1}; finding remains separate from hiring/securing.`,'good');return count;}
function hire(s,mid,oid,employment='free'){let m=merc(s,mid);if(m.status!=='Candidate'||m.expires<s.turn||m.baseId!==operating(s).id)error('Choose an available local candidate.');if(!['free','retained'].includes(employment))error('Choose an employment type.');if(employment==='retained'&&s.reputation<20)error('Retained recruitment requires Friendly Reputation (20).');if(rosterCount(s)>=operativeCapacity(s))error('Operative Capacity is full. Release an eligible operative or improve Reputation before hiring.');const cost=2*wage(m.level);spend(s,oid,'Recruit Operative: '+m.name,1,cost);m.employment=employment;m.status='Onboarding';m.readyAt=s.turn+1;s.metrics.hires++;log(s,'Recruit onboarding',`${m.name}: ${employment==='retained'?'exclusive retained':'nonexclusive free-agent'} agreement starts next Upkeep. Hiring ${cost}; assignment ${assignmentWage(m)}, monthly retainer ${retainer(m)}.`, 'good');}

function trainingCost(s,ids,fid=null){const f=fid?s.facilities.find(f=>f.id===fid):localFacility(s,'training_suite');const occupied=s.cohorts.filter(c=>c.active&&!c.waiting&&c.facilityId===f?.id).reduce((n,c)=>n+c.ids.length,0);const supplied=f&&facilityOperational(s,f)&&occupied+ids.length<=6;if(ids.length>4&&!supplied)error('This cohort needs a funded suite with six-person capacity. Release or renew its instructor.');return (supplied?0:50-(s.guildFeats.includes('cadre')?25:0))+25*ids.length;}

function trainingCapacity(s){const f=localFacility(s,'training_suite');if(!f)return 4;const occupied=s.cohorts.filter(c=>c.active&&!c.waiting&&c.facilityId===f.id).reduce((n,c)=>n+c.ids.length,0);return Math.max(4,6-occupied);}

function train(s,ids,oid){if(!ids.length||ids.length>trainingCapacity(s)||new Set(ids).size!==ids.length)error('Select one to '+trainingCapacity(s)+' unique trainees.');let members=ids.map(i=>merc(s,i));ensureFundedMercs(s,members);if(members.some(m=>!available(m)||m.baseId!==operating(s).id))error('Training requires Available local staff.');let cost=trainingCost(s,ids);spend(s,oid,'Run Training Drills',1,cost);const suite=localFacility(s,'training_suite'),used=s.cohorts.filter(c=>c.active&&!c.waiting&&c.facilityId===suite?.id).reduce((n,c)=>n+c.ids.length,0);let c={id:id(s,'t'),baseId:operating(s).id,facilityId:suite&&used+ids.length<=6?suite.id:null,ids:[...ids],block:1,due:s.turn+1,active:true};s.cohorts.push(c);members.forEach(m=>m.status='Training');log(s,'Training begins',`${ids.length} operatives commit for 30 days. Cost ${cost}; 150 XP each at next Upkeep. Trainer is included in the quote or supplied by the funded facility; the officer remains available.`,'good');}
function promote(s,oid){if(s.campaignTurn===s.turn||s.promotionTurn===s.turn)error('Choose one public promotion or Sector Campaign per turn.');spend(s,oid,'Promote the Guild',1,50);s.promotionTurn=s.turn;let d=rollAdmin(s,oid,'Promote the Guild');let n=V.promotion_reputation_by_degree[d];changeRep(s,n);log(s,'Public reputation',`${n>=0?'+':''}${n} Reputation. ${names[d]}.` ,n<0?'bad':'good');}
function morale(s,ids,oid){if(!ids.length||new Set(ids).size!==ids.length)error('Select personnel to include.');let members=ids.map(i=>merc(s,i));if(members.some(m=>m.moraleTurn===s.turn))error('Each operative may join one morale program per turn.');if(members.some(m=>m.baseId!==operating(s).id||!['Available','Recovering'].includes(m.status)))error('This local program can reach Available or Recovering crew.');spend(s,oid,'Boost Morale',1,10*ids.length);let d=rollAdmin(s,oid,'Boost Morale');let n=V.morale_loyalty_by_degree[d];members.forEach(m=>{m.moraleTurn=s.turn;changeLoyalty(s,m,n);});log(s,'Crew recognition',`${names[d]}: ${n>=0?'+':''}${n} Loyalty for ${ids.length} staff. Reputation is separate.`,n<0?'bad':'good');}
function recon(s,cid,oid,p=1){const c=offer(s,cid);if(c.status!=='Accepted')error('Recon prepares an accepted, undeployed contract.');if(c.preparation)error('This job already has a recorded recon attempt; no free repeat on unchanged facts.');let o=checkAction(s,oid);checkTrained(o,'Computers');if(!Number.isInteger(p)||p<0||p>2)error('Choose a phase.');spend(s,oid,'Conduct Digital Recon');let d=rollAdmin(s,oid,'Digital Recon','Computers');let bonus=[-1,0,1,2][d];c.preparation={phase:p,bonus,expires:s.turn+1};log(s,'Recon briefing',`${phases[p]} on ${c.name}: ${bonus>=0?'+':''}${bonus}. Applies once; highest circumstance bonus only. No mission roll added.`,bonus<0?'bad':'good');}
function broker(s,oid,level=1){if(s.reputation<20)error('Exclusive brokerage requires Friendly Reputation (20).');level=Number(level);if(!Number.isInteger(level)||level<1||level>Math.min(20,2*s.guildLevel+1))error('Choose an available target level.');let o=checkAction(s,oid);checkTrained(o,'Diplomacy');spend(s,oid,'Broker Exclusive Deal',1,50);let d=rollAdmin(s,oid,'Exclusive brokerage','Diplomacy');let count=d>=2?d-1:0;for(let i=0;i<count;i++)addOffer(s,'generated',level,{kind:'exclusive'});log(s,'Exclusive leads',`${count} deadline-bound offers. Securing is separate; only accept when staff can deploy immediately.`,'note');}
function recover(s,ids,oid){if(!ids.length||ids.length>4||new Set(ids).size!==ids.length)error('Select one to four returned operatives.');let members=ids.map(i=>merc(s,i));if(members.some(m=>m.baseId!==operating(s).id||m.status!=='Recovering'))error('Medical care requires returned Recovering personnel.');if(members.some(m=>m.recoveryTurn===s.turn))error('Each operative may receive one recovery protocol per turn.');let o=checkAction(s,oid);checkTrained(o,'Medicine');spend(s,oid,'Establish Recovery Protocol',1,25*ids.length);let d=rollAdmin(s,oid,'Recovery Protocol','Medicine');let reduce=d>=2?d-1:0;for(const m of members){m.recoveryTurn=s.turn;m.readyAt=Math.max(s.turn,m.readyAt-reduce);if(m.readyAt<=s.turn)m.status='Available';}log(s,'Medical care',`${names[d]}: remaining recovery reduced by ${reduce}, after actual return. Staff whose timer reaches zero are Available now.`,'good');}
function facilityQuote(type,repair=false){const f=V.facilities[type];if(!f||!['training_suite','infirmary','recruitment_office','comms_hub'].includes(type))error('That facility is outside this demo.');return {turns:repair?1:f.turns,cost:(repair?round(f.cost*.2):f.cost)+100*(repair?1:f.turns),overhead:f.monthly+f.staff_monthly,assetMonthly:f.monthly,staffMonthly:f.staff_monthly};}

function project(s,type,oid,repairId=null,bid=s.operatingBase||s.primaryBase){if(!repairId&&s.guildLevel<V.development_unlocks.installations)error('New installations unlock at Guild Level 2.');const b=base(s,bid);if(!baseOperational(s,b))error('Choose an operational, staffed base.');let active=s.projects.filter(p=>!p.done);if(active.length>=V.project_capacity[s.guildLevel])error('The guild has reached concurrent project capacity.');let current=repairId?s.facilities.find(f=>f.id===repairId):null;if(repairId&&(!current||current.condition!=='Damaged'||current.baseId!==bid))error('Choose a damaged local facility.');if(!repairId&&locationSlots(s,bid).free<1)error('This base has no unreserved upgrade slot.');if(!repairId&&(s.facilities.some(f=>f.type===type&&(f.baseId===bid||f.transfer?.to===bid))||active.some(p=>p.type===type&&!p.repairId&&p.baseId===bid)))error('This base already has that installation or project.');if(bid!==operating(s).id)error('Select the destination as your operating location first.');let q=facilityQuote(type,!!repairId);spend(s,oid,(repairId?'Repair ':'Commission ')+type,1,q.cost);s.projects.push({id:id(s,'p'),baseId:bid,type,due:s.turn+q.turns,repairId,done:false,cost:q.cost});log(s,'Project commissioned',`${b.name}: ${q.cost} funded including ${100*q.turns} external manager. Completes Turn ${s.turn+q.turns}; staff ${q.staffMonthly} due on activation, asset ${q.assetMonthly} due the following boundary.`, 'good');}

function optimize(s,fid,oid){let f=s.facilities.find(x=>x.id===fid);if(!f)error('Choose an installed facility.');if(f.saving&&f.saving.turn===s.turn+1)error('That next bill already has an optimization attempt.');let o=checkAction(s,oid);checkTrained(o,'Crafting');spend(s,oid,'Optimize Infrastructure');let d=rollAdmin(s,oid,'Optimize Infrastructure','Crafting');f.saving={turn:s.turn+1,rate:[0,0,.1,.2][d]};log(s,'Maintenance plan',`${names[d]}: ${round(f.saving.rate*100)}% saving on this installation’s next overhead, rounded down. Rent, payroll and debt are unaffected.`,'good');}
function chooseLeaderFeat(s,mid,fid){const m=merc(s,mid);if(m.level<5||m.leaderFeat||!leaderFeats.some(f=>f.id===fid))error('This operative cannot make that feat choice.');m.leaderFeat=fid;log(s,m.name+' gains a Leader Feat',leaderFeats.find(f=>f.id===fid).name,'good');}
function availableGuildFeats(s){return guildFeats.filter(f=>s.guildLevel>=f.level&&!s.guildFeats.includes(f.id)&&(!f.requires||s.guildFeats.includes(f.requires)));}
function chooseGuildFeat(s,fid){if(s.phase!=='advancement'||s.featChoices<1||!availableGuildFeats(s).some(f=>f.id===fid))error('No eligible Guild Feat choice is pending.');s.guildFeats.push(fid);s.featChoices--;log(s,'Guild Feat earned',guildFeats.find(f=>f.id===fid).name,'good');}
function makeEvent(s){let n=(die(s.seed,'event',s.turn)-1)%3;if(n===0)return {type:'lead',title:'A contact calls in a favor',text:'Helix Transit has another ordinary delivery assignment. Take the lead now; securing and deployment wait for next turn’s Activity.'};if(n===1){let m=s.mercs.find(m=>!['Candidate','Expired','Inactive','Released','Missing','Captured','Dead'].includes(m.status));return {type:'concern',member:m?.id,title:'The crew wants to be heard',text:(m?m.name:'A crew member')+' is frustrated by long hours and unclear expectations. Loyalty falls by 3. You can acknowledge it now; a funded Boost Morale action can follow next turn.'};}return {type:'community',title:'An invitation from the dockworkers',text:'A local association offers an introduction. Accept to improve its separate Relations by one step, up to Friendly; no cash or contract is automatic.'};}
function endActivity(s){if(s.phase!=='activity')error('Finish the current step first.');s.unusedHistory=s.unusedHistory||[];s.unusedHistory.push({turn:s.turn,shared:s.actions,officers:s.officers.map(o=>({name:o.name,actionsLed:o.used}))});s.phase='event';s.operations={settled:false,choices:[],complete:false};s.event=null;if(!nextJob(s))settleOperations(s);}
function finishOperations(s){if(s.phase!=='event'||!s.operations?.settled||s.operations.pendingReview||s.operations.choices.length)error('Finish all contract results and payment decisions first.');s.operations.complete=true;if(s.resumePhase==='upkeep'){delete s.resumePhase;s.phase='upkeep';if(!s.upkeep?.prepared)prepareUpkeep(s);return;}if(s.resumePhase==='advancement'){delete s.resumePhase;settleGuildXP(s);s.phase='advancement';return;}if(!s.event){s.event=makeEvent(s);if(s.event.type==='concern'&&s.event.member)changeLoyalty(s,merc(s,s.event.member),-3);log(s,'Guild Event: '+s.event.title,s.event.text,'event');}}
function settleGuildXP(s){s.guildXP+=s.pendingGuildXP;s.pendingGuildXP=0;while(s.guildXP>=1000&&s.guildLevel<10){s.guildXP-=1000;s.guildLevel++;if(V.guild_feat_levels.includes(s.guildLevel)){if(s.legacyFeatCredit>0)s.legacyFeatCredit--;else s.featChoices++;}log(s,'Guild reaches Level '+s.guildLevel,V.guild_feat_levels.includes(s.guildLevel)?'A Guild Feat is earned. The larger shared action pool starts next turn.':`Development unlock: ${s.guildLevel===2?'installations and unsecured loans':s.guildLevel===4?'new bases, outposts and secured loans':V.project_capacity[s.guildLevel]+' concurrent projects'}. The larger shared action pool starts next turn.`,'good');}}
function respondEvent(s,choice){if(s.phase!=='event'||!s.event||!s.operations?.complete)error('Finish contract resolution before responding to the monthly event.');if(choice==='accept'&&s.event.type==='lead'){addOffer(s,'cargo',1+Math.floor((s.turn-1)/6),{expires:s.turn+2});log(s,'Lead held for next turn','No free securing, deployment or cash. The contact leaves this offer open through next turn.');}if(choice==='accept'&&s.event.type==='community'){s.relations=Math.min(3,s.relations+1);log(s,'Introductions accepted','Dockworkers Relations improve; this is separate from public Reputation.','good');}if(s.event.type==='concern')log(s,'Concern acknowledged','There is no automatic Loyalty recovery. Consider an actual morale investment next Activity.');settleGuildXP(s);s.phase='advancement';}
function bill(s,creditor,amount,type='rent'){if(amount<=0)return;let paid=Math.min(s.cash,amount);if(paid)money(s,-paid,creditor,type);if(paid<amount){s.arrears.push({id:id(s,'a'),creditor,amount:amount-paid,type,turn:s.turn});log(s,'Unpaid obligation',`${creditor}: ${amount-paid} remains owed. This demo records creditor-specific arrears; it does not simulate full eviction or collection.`, 'bad');}}
function payArrears(s,limit=s.cash){if(s.phase!=='activity')error('Pay arrears during routine Activity administration.');if(!s.arrears.length)error('No arrears are owed.');if(!s.cash)error('No treasury funds are available.');if(!Number.isInteger(limit)||limit<1||limit>s.cash)error('Choose a positive payment budget within available cash.');let budget=limit;for(const b of s.arrears){let n=Math.min(b.amount,s.cash,budget);budget-=n;if(b.service?.type==='loan'){applyLoanPayment(s,b.service,n);b.service.paid+=n;}b.amount-=n;if(n)money(s,-n,'Arrears: '+b.creditor,b.type);if(b.amount===0&&b.service&&b.turn===s.turn)paidService(s,b.service);}s.arrears=s.arrears.filter(b=>b.amount>0);for(const l of s.loans||[])refreshLoan(s,l);log(s,'Arrears payment','Only actual funded amounts were paid; this routine payment spent no Guild Action.','good');}
function advance(s){if(s.phase!=='advancement')error('Complete the event and advancement step.');s.turn++;s.phase='upkeep';s.upkeep={settled:false,choices:[],complete:false};s.actions=0;s.officers.forEach(o=>o.used=0);s.trustedUsed=false;s.pipelineUsed=false;s.event=null;s.operations=null;s.lastRoll=null;for(const c of s.board)if(c.status==='Offer'&&c.expires<s.turn)c.status='Expired';for(const m of s.mercs){if(m.status==='Candidate'&&m.expires<s.turn)m.status='Expired';if(m.leaveAt&&m.leaveAt<=s.turn){if(m.loyalty===0)m.status='Inactive';delete m.leaveAt;}if(['Onboarding','Recovering','In Transit'].includes(m.status)&&m.readyAt<=s.turn){m.status='Available';log(s,m.name+' is Available','Scheduled onboarding or recovery is complete.');}}prepareUpkeep(s);}
function nextJob(s){return s.jobs.find(j=>j.due<=s.turn&&!j.settled&&j.rolls.length<3);}
function rollPhase(s){if(s.phase!=='event'||s.operations?.settled)error('Resolve operations during Events.');if(s.operations.pendingReview)error('Review the recorded phase result before continuing.');let j=nextJob(s);if(!j)error('All due checks are already rolled.');let p=j.rolls.length,persistent=j.rolls.filter(r=>r.degree===0).length*-2,prev=p?j.rolls[p-1].degree:null,next=prev===1?-1:prev===3?1:0,check=j.quote.checks[p],face=die(s.seed,'mission',j.departure,j.contract.id,p),mod=check.modifier+persistent+next,d=degree(face,mod,check.dc),complication=phaseComplication(s,j,p,d);const result={...check,face,actualModifier:mod,total:face+mod,forward:persistent+next,degree:d,complication};j.rolls.push(result);s.operations.pendingReview={job:j.id,phase:p};log(s,j.contract.name+' · '+phases[p],`${check.leadName} (${check.skill}): d20 ${face} +${mod} =${face+mod} vs DC${check.dc}: ${names[d]}.${complication?' '+complication.text:''} Pending review; consequences apply at settlement.`,'roll');return result;}

function completionRule(c,card=contractRule(c)){return `Any ${card.required_successes} of 3 phases must succeed.`;}
function missionOutcome(j){const card=j.quote.contractRules||j.rulesSnapshot||contractRule(j.contract),successfulPhases=j.rolls.filter(r=>r.degree>=2).length,requiredSuccesses=card.required_successes,success=successfulPhases>=requiredSuccesses;return {success,successfulPhases,requiredSuccesses,essentialMet:true,completionReason:`${successfulPhases} of 3 phases succeeded; ${requiredSuccesses} required.`};}
function settleOperations(s){if(s.operations.settled)return;if(nextJob(s)||s.operations.pendingReview)error('Resolve and review all due mission checks first.');let due=s.jobs.filter(j=>j.due<=s.turn&&!j.settled);for(const j of due){let card=j.quote.contractRules||j.rulesSnapshot||contractRule(j.contract);const outcome=missionOutcome(j),success=outcome.success;j.result={...outcome,complications:j.rolls.map((r,p)=>r.complication||phaseComplication(s,j,p,r.degree)).filter(Boolean)};if(success)money(s,j.quote.payout,j.contract.name,'client');}
 for(const j of due){let card=j.quote.contractRules||j.rulesSnapshot||contractRule(j.contract),success=j.result.success;let phaseRecovery=j.rolls.some(r=>r.degree===0)?1:0;let passive=j.quote.leaderFeat==='hardcase'||!!localFacility(s,'infirmary',j.baseId||s.primaryBase)?1:0;let recovery=Math.max(card.mandatory_recovery,Math.max(0,phaseRecovery-passive));j.result.recovery=recovery;j.settled=true;let eligible=new Set();for(const r of j.rolls)if(r.degree>=2){eligible.add(r.lead);for(const h of r.supporters)if(h.marginal>0&&degree(r.face,r.actualModifier-h.marginal,r.dc)<r.degree)eligible.add(h.id);}for(const i of j.ids){let m=merc(s,i);xp(s,m,card.participation_xp+(success?card.completion_xp:0));m.status=recovery?'Recovering':'Available';m.readyAt=s.turn+(j.legacyBoundaryReturn?0:1)+recovery;if(success&&j.quote.leaderFeat==='advocate')changeLoyalty(s,m,1);}if(success){s.metrics.completed++;j.result.guildXP=j.quote.guildAward?.xp??card.guild_xp;s.pendingGuildXP+=j.result.guildXP;if(j.leader)xp(s,merc(s,j.leader),50);if(!s.contacts.includes(j.contract.client))s.contacts.push(j.contract.client);bill(s,'Successful wages: '+j.contract.name,j.quote.pay,'wages');s.operations.choices.push({id:id(s,'u'),type:'mvp',job:j.id,eligible:[...eligible]});}else{s.metrics.failed++;s.operations.choices.push({id:id(s,'u'),type:'failedPay',job:j.id});}changeRep(s,success?card.reputation_success:card.reputation_failure);offer(s,j.contract.id).status=success?'Completed':'Failed';log(s,success?'Contract completed':'Contract failed',`${j.contract.name}: ${j.result.completionReason} ${success?j.quote.payout+' client credits, completion operative XP and '+j.result.guildXP+' Guild XP.':'zero client cash; participation XP only.'} Recovery ${recovery}; Reputation ${success?'+'+card.reputation_success:card.reputation_failure}.`,success?'good':'bad');}
 for(const j of due){applyContingency(s,j);j.result.exceptionalPerformance=j.rolls.length===3&&j.rolls.every(r=>r.degree===3);if(j.result.exceptionalPerformance){const rating=j.quote.guildAward||contractThreat(s,j.contract);j.result.exceptionalGuidance=rating.index===0?'Flawless execution. Routine or Trivial work does not normally merit a Hero Point.':'Exceptional performance: the GM may award one Hero Point to one PC for meaningful leadership or preparation. No automatic payout or XP bonus; use the existing GM award control.';log(s,'Exceptional performance',j.contract.name+': '+j.result.exceptionalGuidance,'good');}for(const c of j.result.complications){if(c.type==='injury'){const m=merc(s,c.lead);if(m.status!=='Missing'){m.status='Recovering';m.readyAt=Math.max(m.readyAt||s.turn+1,s.turn+1+c.recovery);}}else if(c.type==='repairs')bill(s,'Transport repairs: '+j.contract.name,c.amount,'repairs');else if(c.type==='missing'){const m=merc(s,c.lead);m.status='Missing';delete m.readyAt;}log(s,'Mission complication',j.contract.name+' · '+phases[c.phase]+': '+c.text,'bad');}const r=j.quote.contractRules||j.rulesSnapshot||contractRule(j.contract);if(j.result.success&&r.additional_reward){let index=(die(s.seed,'referral',j.id)-1)%people.length,m=makeMerc(s,people[index],j.contract.level);m.baseId=j.baseId;m.referredBy=j.contract.client;m.status='Candidate';m.expires=s.turn+1;s.mercs.push(m);j.result.additionalReward='Specialist referral: '+m.name+'; hire normally before end of Turn '+m.expires+'.';if(r.additional_reward==='recruit_and_contact'){const contact='Ghost Fleet Liaison';if(!s.contacts.includes(contact))s.contacts.push(contact);j.result.additionalReward+=' New client contact: '+contact+'.';}log(s,'Additional contract reward',j.result.additionalReward,'good');}}
 for(const c of s.board)if(c.status==='Accepted'&&c.deployBy<=s.turn){c.status='Expired';if(c.kind==='exclusive'){s.metrics.failed++;changeRep(s,V.contracts.exclusive.reputation_failure);log(s,'Exclusive deadline breached',`${c.name}: no meaningful attempt, no XP or payout; Reputation −4.`, 'bad');}else log(s,'Ordinary contract expired',c.name+': uncompleted, no rewards and no Reputation penalty.');}
 s.operations.settled=true;log(s,'Contract settlement complete','All due client receipts arrived before successful payroll. Choose failed-job wages and MVP before the monthly event.');}

function choice(s,cid,value){let settlement=s.phase==='event'?s.operations:s.phase==='upkeep'?s.upkeep:null;if(!settlement?.settled)error('Resolve due work first.');let c=settlement.choices.find(x=>x.id===cid);if(!c)error('That choice is already settled.');if(c.type==='failedPay'){let j=s.jobs.find(x=>x.id===c.job);if(!['full','half','none'].includes(value))error('Choose full, half or no failed-job wages.');let amount=round(j.quote.pay*({full:1,half:.5,none:0}[value]));checkFunds(s,amount);if(amount)money(s,-amount,'Failed wages: '+j.contract.name,'failedWages');j.failedPay=value;j.ids.forEach(i=>changeLoyalty(s,merc(s,i),V.failed_pay_loyalty[value]));log(s,'Failed-job pay chosen',`${value}: ${amount} credits actually paid; Loyalty ${V.failed_pay_loyalty[value]>=0?'+':''}${V.failed_pay_loyalty[value]}. Waived remainder creates no default debt, and Reputation is unchanged.`,'note');}else if(c.type==='mvp'){if(value!=='none'&&!c.eligible.includes(value))error('Choose a materially contributing eligible operative, or no MVP.');let j=s.jobs.find(x=>x.id===c.job);if(value!=='none'){xp(s,merc(s,value),50);j.mvp=value;log(s,'MVP recognized',merc(s,value).name+' gains 50 XP for documented contribution.','good');}}else if(c.type==='training'){let cohort=s.cohorts.find(x=>x.id===c.cohort);if(value==='continue'){ensureFundedMercs(s,cohort.ids.map(i=>merc(s,i)));let cost=trainingCost(s,cohort.ids,cohort.facilityId||'offsite');checkFunds(s,cost);money(s,-cost,'Consecutive training block','training');cohort.block++;cohort.due=s.turn+1;cohort.waiting=false;log(s,'Training continues',`Block ${cohort.block} funded for ${cost}. No new action; cohort remains Training. Next block bonus is not retroactive.`,'good');}else if(value==='stop'){cohort.active=false;cohort.waiting=false;cohort.ids.forEach(i=>merc(s,i).status='Available');log(s,'Training ends','Crew are Available; the consecutive streak has ended.');}else error('Choose continue or stop.');}settlement.choices=settlement.choices.filter(x=>x.id!==cid);}
function finishUpkeep(s){if(s.phase!=='upkeep'||!s.upkeep.settled||s.upkeep.choices.length)error('Complete all Upkeep decisions first.');s.actions=actionPool(s);s.phase='activity';s.upkeep.complete=true;if(s.guildFeats.includes('standing'))addOffer(s,'generated',1+Math.floor((s.turn-1)/6),{standing:true,kind:'standard',client:'Helix Transit'});log(s,'Budget resets',`${s.actions} shared actions; no separate officer action limit. Give each player first choice before allocating remaining actions. Routine deployment needs no action. Development XP from Upkeep and contract XP from Events settle at end of this turn.`,'good');}
function summary(s){let completed=s.jobs.filter(j=>j.settled);return ['# Guildmaster browser playtest','Rules: 0.3.11 · Setup: '+s.preset+' · Seed: '+s.seed+' · Acquisition: '+(s.freeAcquisition?'free':'one action'),'Guild Turn '+s.turn+' · Phase '+s.phase,'PC party size: '+s.partySize+' · Shared pool: '+actionPool(s)+' · Remaining: '+s.actions,'Initial liquid funds: '+s.initialCash,'Bases: '+s.bases.map(b=>b.name+' '+b.status+' '+b.monthly+'/month').join('; '),'Facilities: '+s.facilities.map(f=>V.facilities[f.type].name+' at '+base(s,f.baseId).name+' '+(facilityOperational(s,f)?'staffed operational':'inactive')+' '+facilityQuote(f.type).overhead+'/month').join('; '),'Known next Upkeep: '+forecast(s)+' (mission wages and optional spending separate)','Loans: '+(s.loans||[]).map(l=>l.id+' '+l.type+' '+l.remaining+' principal '+l.status+' collateral '+(l.collateral||'none')).join('; '),'Treasury: '+s.cash+' · Arrears: '+s.arrears.reduce((a,x)=>a+x.amount,0),'Guild Level: '+s.guildLevel+' · Guild XP: '+s.guildXP+' + '+s.pendingGuildXP+' pending','Contracts completed/failed: '+s.metrics.completed+'/'+s.metrics.failed,'Roster: '+s.mercs.filter(m=>!['Candidate','Expired'].includes(m.status)).map(m=>m.name+' '+m.employment+' at '+base(s,m.baseId).name+' L'+m.level+' '+m.status+' XP'+m.xp+' Loyalty'+m.loyalty).join('; '),'','## Feedback',s.feedback||'(No notes yet)','',...s.log.slice().reverse().map(l=>'T'+l.turn+' · '+l.title+' — '+l.text)].join('\n');}
function migrateLegacy(s){if(s.rules==='0.3.2')return s;if(s.rules!=='0.3.1')error('Unsupported saved rules.');let legacy=s.phase;s.rules='0.3.2';for(const j of s.jobs)if(!j.settled){j.due=s.turn;j.legacyBoundaryReturn=legacy==='upkeep';};s.operations=null;if(legacy!=='activity'&&s.jobs.some(j=>!j.settled)){s.phase='event';s.operations={settled:false,choices:[],complete:false};if(legacy==='upkeep'||legacy==='advancement')s.resumePhase=legacy;if(!nextJob(s))settleOperations(s);}else if(legacy==='event')s.operations={settled:true,choices:[],complete:true};log(s,'Playtest updated to 0.3.2','Contracts resolve in Events. Existing rolls and frozen quotes are retained; new deployments use the explicit size circumstance bonus.');return s;}
function migrate033(s){if(s.rules==='0.3.3'||s.rules==='0.3.4')return s;if(!['0.3.1','0.3.2'].includes(s.rules))error('Unsupported saved rules.');if(s.rules==='0.3.1')migrateLegacy(s);s.rules='0.3.3';s.partySize=s.partySize||4;const profiles=partyOfficers(s.partySize);for(const o of profiles){const existing=s.officers.find(x=>x.id===o.id);if(existing){existing.name=o.name;existing.role=o.role;}else s.officers.push(o);}if(s.phase==='activity'){const spent=s.actionHistory.filter(h=>h.turn===s.turn).reduce((n,h)=>n+h.cost,0);s.actions=Math.max(0,actionPool(s)-spent);}log(s,'Playtest updated to 0.3.3','Shared pool = PCs + Guild Level − 1; officer action caps removed. Failed-job pay now changes Loyalty +5 / 0 / −5. Past payments and recorded outcomes remain unchanged.');return s;}

function migrate034(s){if(s.rules==='0.3.4')return s;migrate033(s);const legacyPhase=s.phase;s.rules='0.3.4';s.preset='migrated';s.initialCash=s.initialCash||2000;s.bases=[{id:'hq',type:'leased_station_hq',name:'Station Operations Office',region:'Station Meridian',status:'Operational',readyAt:1,slots:2,monthly:300,chief:null,milestone:true}];s.primaryBase='hq';s.operatingBase='hq';for(const m of s.mercs){m.baseId='hq';m.employment='free';}for(const c of s.board)c.baseId='hq';for(const j of s.jobs)j.baseId='hq';for(const c of s.cohorts)c.baseId='hq';for(const p of s.projects)p.baseId='hq';for(const f of s.facilities){f.baseId='hq';f.landlordOwned=false;f.staff={name:V.facilities[f.type].staff_name,monthly:V.facilities[f.type].staff_monthly,active:true,paidTurn:s.turn};}if(s.upkeep){s.upkeep.prepared=true;s.upkeep.invoice=[];s.upkeep.changes=[];if(!s.upkeep.settled&&(legacyPhase==='upkeep'||s.resumePhase==='upkeep')){s.upkeep.prepared=false;prepareUpkeep(s);}}log(s,'Playtest updated to 0.3.4','Bases and staffed facilities added. Previous rolls, cash, wages and paid intervals are preserved. New 300-credit lease and staff bills begin at the next unpaid Upkeep; no free starting installation added.');return s;}


function migrate035(s){if(s.rules==='0.3.5')return s;migrate034(s);for(const j of s.jobs)if(!j.quote.contractRules&&!j.rulesSnapshot)j.rulesSnapshot=JSON.parse(JSON.stringify(V.legacy_contracts_034[j.contract.kind]));for(const c of s.board)if(['Offer','Accepted'].includes(c.status)){const template=templates.find(t=>t.key===c.key);if(template)c.description=template.description;}s.rules='0.3.5';s.rollHistory=s.rollHistory||[];if(s.lastRoll&&!s.rollHistory.length)s.rollHistory.push({...s.lastRoll});if(s.phase==='event'&&s.operations&&!s.operations.complete){const j=s.jobs.find(j=>j.rolls.length&&!j.settled);if(j)s.operations.pendingReview={job:j.id,phase:j.rolls.length-1};}log(s,'Playtest updated to 0.3.5','New deployments use five difficulty bands and three distinct leads. Already deployed wage quotes, DCs, completion rules and prior rolls remain frozen. Expansion gates and base/Normal payout values are unchanged.');return s;}

function migrate036(s){if(s.rules==='0.3.6')return s;migrate035(s);s.loans=s.loans||[];const earned=V.guild_feat_levels.filter(l=>l<=s.guildLevel).length;s.legacyFeatCredit=Math.max(0,s.guildFeats.length+s.featChoices-earned);s.rules='0.3.6';log(s,'Playtest updated to 0.3.6','Development gates: installations/ordinary loans 2, property/secured loans 4. Feats now at odd levels from 3; existing awards and projects are retained. Loan proceeds are financing, separate from client income.');return s;}
function migrate037(s){if(s.rules==='0.3.7')return s;migrate036(s);for(const j of s.jobs)if(j.quote.repairWage===undefined)j.repairWageSnapshot=5*round(50*1.25**(j.contract.level-1)/5);s.rules='0.3.7';log(s,'Playtest updated to 0.3.7','New quotes use Normal Level 1 payout 900 and ordinary operative pay 110, with existing level growth and employment ratios. Deployed wages, payouts, rolls and repair basis stay frozen; prepared bills remain unchanged.');return s;}
function migrate038(s){if(s.rules==='0.3.8')return s;migrate037(s);for(const j of s.jobs)if(j.result){const outcome=missionOutcome(j);if(outcome.success===j.result.success)j.result.completionReason=outcome.completionReason;}s.rules='0.3.8';log(s,'Playtest updated to 0.3.8','Mission cards now state completion requirements prominently, including required phases. Results explain the success count and any failed required phase. Previous rolls, outcomes and financial settlement remain unchanged.');return s;}
function migrate039(s){if(s.rules==='0.3.9')return s;migrate038(s);s.heroSession=s.heroSession||1;heroPCs(s).forEach(o=>{if(!Number.isInteger(o.heroPoints))o.heroPoints=V.hero_points.per_session;});for(const c of s.board)if(['Offer','Accepted'].includes(c.status)){delete c.essential;if(c.key==='relay')c.description=templates.find(t=>t.key==='relay').description;}for(const j of s.jobs)if(!j.settled){delete j.contract.essential;if(j.contract.key==='relay')j.contract.description=templates.find(t=>t.key==='relay').description;}s.discoveryHistory=s.discoveryHistory||[];s.rules='0.3.9';log(s,'Playtest updated to 0.3.9','Unsettled missions use only their printed success count. PCs start this test session with 1 Hero Point; reroll a pending phase once, keep the second. Network discovery is normally 3 random-quality results. Automatic Upkeep funds current obligations before old arrears. Past settlements and debt balances remain.');return s;}
function migrate0310(s){if(s.rules==='0.3.10')return s;migrate039(s);initializeMilestones(s);if(s.actionHistory.some(h=>h.turn===s.turn&&h.action==='Promote the Guild'))s.promotionTurn=s.turn;s.rules='0.3.10';log(s,'Playtest updated to 0.3.10','New deployments use relative-threat Guild XP; 1,000 XP per level. Past XP and deployed quotes remain. Existing developments count as established milestone categories without retroactive awards. New multi-action officer activities and advancing administrative benchmarks are available; no automatic flawless-job reward.');return s;}
function migrate(s){if(s.rules==='0.3.11')return s;migrate0310(s);initializeContent(s);for(const m of s.mercs){if(m.contentVersion)continue;const original=m.name,profile=people.find(p=>original===p.name||original===p.name+' · referral'||original.startsWith(p.name+' ')&&/^\d+$/.test(original.slice(p.name.length+1)));if(profile){const identity=C.identity(s.seed,m.id,{callSign:profile.name,usedNames:s.mercs.filter(x=>x.id!==m.id).map(x=>x.name)});Object.assign(m,identity);m.previousName=original;}else {m.contentVersion=1;m.ancestry=m.ancestry||'Not recorded';}}for(const c of s.board){const template=templates.find(t=>t.key===c.key);if(c.contentVersion||c.status!=='Offer'||c.expires<s.turn||!template||!C.clients.some(client=>client.name===c.client)||!(c.name===template.name||c.name.startsWith(template.name+' · Lead ')&&/^\d+$/.test(c.name.slice((template.name+' · Lead ').length))))continue;const content=C.mission(s.seed,c.id,C.legacyAliases[c.key],{client:c.client,usedNames:s.board.filter(x=>x.id!==c.id).map(x=>x.name)});const skills=c.skills;Object.assign(c,content);c.skills=skills;}s.rules='0.3.11';log(s,'Playtest updated to 0.3.11','Ancestry-aware names and character backgrounds replace default numbered identities; call signs preserve recognition. New leads use30 mission archetypes and local lore dossiers. Accepted/deployed mission text, rolls, skills, rewards, cash and personnel IDs remain. Custom names are preserved.');return s;}

function averageRevenue(s){const turns=Array.from({length:Math.min(V.loan.revenue_window,s.turn-1)},(_,i)=>s.turn-1-i);return turns.length?s.ledger.filter(l=>l.category==='client'&&turns.includes(l.turn)).reduce((n,l)=>n+Math.max(0,l.amount),0)/turns.length:0;}
function outstandingLoanArrears(s,lid){return s.arrears.filter(a=>a.service?.type==='loan'&&a.service.reference===lid&&a.amount>0);}
function refreshLoan(s,l){const arrears=outstandingLoanArrears(s,l.id);l.status=arrears.length?(Math.min(...arrears.map(a=>a.turn))<s.turn?'Default':'Delinquent'):l.remaining<=0?'Paid':'Current';}
function loanDue(s,l,turn=s.turn+1){if(l.remaining<=0||l.startAt>turn)return {principal:0,interest:0,total:0};const reserved=outstandingLoanArrears(s,l.id).reduce((n,a)=>n+Math.max(0,a.amount-Math.max(0,a.service.loanInterest-a.service.paid)),0);const unbilled=Math.max(0,l.remaining-reserved);const principal=Math.min(unbilled,turn>=l.startAt+l.term-1?unbilled:l.installmentPrincipal);const interest=Math.ceil(l.remaining*l.rate);return {principal,interest,total:principal+interest};}
function loanQuote(s,type,amount,collateral=null){if(!['unsecured','secured'].includes(type))error('Choose an unsecured or secured loan.');const level=type==='secured'?V.loan.secured_level:V.loan.unsecured_level;if(s.guildLevel<level)error(`${type==='secured'?'Secured':'Unsecured'} loans unlock at Guild Level ${level}.`);if(s.reputation<V.loan.minimum_reputation)error('Financing requires nonnegative Reputation.');if(s.arrears.some(a=>a.amount>0))error('Cure outstanding arrears before applying for financing.');if(!Number.isInteger(amount)||amount<100||amount%100)error('Request whole hundreds of credits, at least 100.');const active=(s.loans||[]).filter(l=>l.status!=='Paid');let cap=V.loan.unsecured_limit_per_guild_level*s.guildLevel-active.filter(l=>l.type==='unsecured').reduce((n,l)=>n+l.remaining,0);if(type==='secured'){const b=base(s,collateral);if(b.type==='leased_station_hq'||b.status!=='Operational')error('Pledge an operational owned property; leases and future purchases are ineligible.');if(active.some(l=>l.collateral===b.id))error('That property is already pledged.');cap=Math.floor(V.base_market[b.type].purchase_price*V.loan.secured_ltv);}if(amount>cap)error(`This agreement permits at most ${Math.max(0,cap)} credits.`);const rate=type==='secured'?V.loan.secured_monthly_rate:V.loan.unsecured_monthly_rate,principal=Math.ceil(amount/V.loan.term_turns),interest=Math.ceil(amount*rate),payment=principal+interest,revenue=averageRevenue(s),existing=active.reduce((n,l)=>n+loanDue(s,l).total,0),ceiling=Math.floor(revenue*V.loan.debt_service_share);if(existing+payment>ceiling)error(`Debt service ${existing+payment}/month exceeds ${ceiling} (30% of recorded average client receipts ${Math.floor(revenue)}). Complete contracts before applying.`);return {type,amount,rate,term:V.loan.term_turns,installmentPrincipal:principal,interest,payment,collateral:type==='secured'?collateral:null,revenue,ceiling};}
function borrow(s,type,amount,oid,collateral=null){const q=loanQuote(s,type,Number(amount),collateral);spend(s,oid,'Secure Financing: '+type);const l={id:id(s,'loan'),...q,remaining:q.amount,startAt:s.turn+1,status:'Current'};s.loans.push(l);money(s,q.amount,'Loan proceeds: '+l.id,'financing');log(s,'Loan agreement funded',`${q.amount} received; ${q.term} turns, ${q.rate*100}% monthly on outstanding principal. First Upkeep ${l.startAt}: ${q.installmentPrincipal} principal + ${q.interest} interest. First missed bill is Delinquent; uncured at next boundary is Default. Default blocks new finance; collateral remains pledged pending a creditor remedy, with no automatic seizure in this demo.`,'good');return l;}
function applyLoanPayment(s,line,amount){const l=s.loans.find(l=>l.id===line.reference);if(!l)error('Loan invoice has no agreement.');const interestRemaining=Math.max(0,line.loanInterest-line.paid),principal=Math.max(0,amount-interestRemaining);l.remaining=Math.max(0,l.remaining-principal);}
function repayLoan(s,lid,amount){if(s.phase!=='activity')error('Repay during routine Activity.');const l=s.loans.find(l=>l.id===lid);if(!l||l.remaining<=0)error('Choose an outstanding loan.');if(outstandingLoanArrears(s,lid).length)error('Pay this loan’s arrears before additional principal.');if(!Number.isInteger(amount)||amount<1||amount>l.remaining)error('Choose a positive amount within the remaining principal.');checkFunds(s,amount);money(s,-amount,'Principal prepayment: '+lid,'loan');l.remaining-=amount;refreshLoan(s,l);log(s,'Loan principal repaid',`${amount} paid; ${l.remaining} remaining. No action or penalty; future interest is based on the reduced balance.`,'good');}
function loanInvoice(s){for(const l of s.loans||[]){refreshLoan(s,l);const q=loanDue(s,l,s.turn);if(q.total){addInvoice(s,'loan:'+l.id,`${l.id} · ${q.principal} principal + ${q.interest} interest`,q.total,'loan',l.id);const line=s.upkeep.invoice[s.upkeep.invoice.length-1];line.loanInterest=q.interest;line.loanPrincipal=q.principal;}if(l.status==='Default')s.upkeep.changes.push(`${l.id} is in Default: cure arrears. New financing is blocked; collateral remedy requires adjudication.`);}}


function contractThreat(s,c){const complexity=V.guild_threat.complexity[c.kind]??0,offset=c.level-s.guildLevel+complexity;const band=V.guild_threat.offsetBands.find(b=>b.maximum===null||offset<=b.maximum),index=band.index;return {index,label:V.guild_threat.labels[index],xp:V.guild_threat.awards[index],guildLevel:s.guildLevel,missionLevel:c.level,complexity,offset};}
function initializeMilestones(s){if(s.developmentMilestones)return;s.developmentMilestones={headquarters:s.bases.some(b=>b.id===s.primaryBase&&b.type!=='leased_station_hq'&&b.status==='Operational'),outpost:s.bases.some(b=>b.type==='outpost'&&b.chief?.paidTurn>0),facilities:[...new Set(s.facilities.map(f=>f.type))]};}
function claimMilestones(s){initializeMilestones(s);const m=s.developmentMilestones,b=base(s,s.primaryBase),award=(key,label)=>{s.pendingGuildXP+=V.development_milestones[key];s.milestoneHistory=s.milestoneHistory||[];s.milestoneHistory.push({turn:s.turn,key,label,xp:V.development_milestones[key]});log(s,'Development milestone',`${label}: ${V.development_milestones[key]} first-time Guild XP pending.`,'good');};if(!m.headquarters&&b.type!=='leased_station_hq'&&b.type!=='outpost'&&b.status==='Operational'&&b.paidTurn===s.turn){m.headquarters=true;award('headquarters','First funded owned headquarters');}if(!m.outpost&&s.bases.some(b=>b.type==='outpost'&&baseOperational(s,b)&&b.paidTurn===s.turn)){m.outpost=true;award('outpost','First funded staffed outpost');}for(const f of s.facilities)if(!m.facilities.includes(f.type)&&facilityOperational(s,f)){m.facilities.push(f.type);award('facility','First funded '+V.facilities[f.type].name);}}
function advancedOfficer(s,oid,office,k,level,cost){const o=checkAction(s,oid,cost),expected=office==='command'?0:office==='field'?2:3;const pcs=heroPCs(s),actual=pcs.indexOf(o)%4;if(o.baseId||(o.office?o.office!==office:actual!==expected))error('This activity requires the '+({command:'Commander',field:'Operations Officer',liaison:'Personnel Officer'}[office])+'.');if(s.guildLevel<level)error('This activity unlocks at Guild Level '+level+'.');checkTrained(o,k);return o;}
function sectorCampaign(s,oid){const v=V.advanced_actions.campaign;advancedOfficer(s,oid,'command','Diplomacy',v.level,v.actions);if(s.campaignTurn===s.turn||s.actionHistory.some(h=>h.turn===s.turn&&h.action==='Promote the Guild'))error('Choose one Sector Campaign or ordinary promotion this turn.');spend(s,oid,'Launch a Sector Campaign',v.actions,v.cost);s.campaignTurn=s.turn;const d=rollAdmin(s,oid,'Sector Campaign','Diplomacy'),n=v.reputation[d];changeRep(s,n);log(s,'Sector campaign results',`${names[d]}: ${n>=0?'+':''}${n} Reputation. Once per guild this turn; no Guild XP.`,n<0?'bad':'good');}
function operationsBriefing(s,cid,ids,leads,oid,leader=null){const v=V.advanced_actions.briefing,o=officer(s,oid),k=(o.actorUuid?o.skillRanks?.Computers>0:!!o.skills.Computers)?'Computers':'Survival';advancedOfficer(s,oid,'field',k,v.level,v.actions);const c=offer(s,cid);if(c.status!=='Accepted'||c.preparation)error('Brief one accepted, undeployed job with no preparation attempt.');quote(s,c,ids,leads,leader);spend(s,oid,'Prepare an Operations Briefing',v.actions,v.per_operative*ids.length);const d=rollAdmin(s,oid,'Operations Briefing',k);c.preparation={allPhases:d>=2,phase:1,bonus:[-1,0,1,2][d],expires:s.turn+1,lock:{ids:[...ids],leads:[...leads],leader}};log(s,'Operations briefing',`${names[d]}: ${d>=2?'+'+c.preparation.bonus+' circumstance to all three phases':d===0?'-1 Engagement circumstance':'no bonus'}. Squad and leads locked. Replaces Recon; highest circumstance only.`,'good');}
function intensiveTraining(s,ids,oid){const v=V.advanced_actions.intensive;advancedOfficer(s,oid,'liaison','Medicine',v.level,v.actions);const suite=localFacility(s,'training_suite');if(!suite)error('Intensive training requires a funded local Training Suite.');if(!ids.length||new Set(ids).size!==ids.length||ids.length>trainingCapacity(s))error('Select unique trainees within funded training capacity.');const members=ids.map(i=>merc(s,i));if(members.some(m=>!available(m)||m.baseId!==operating(s).id||s.turn-(m.intensiveTurn??-Infinity)<v.cooldown))error('Choose Available local trainees who have not used intensive training in the past three turns.');ensureFundedMercs(s,members);const occupied=s.cohorts.filter(c=>c.active&&!c.waiting&&c.facilityId===suite.id).reduce((n,c)=>n+c.ids.length,0);if(occupied+ids.length>6)error('Funded suite capacity was exceeded.');const cost=trainingCost(s,ids)+25*ids.length;spend(s,oid,'Run an Intensive Training Block',v.actions,cost);s.cohorts.push({id:id(s,'t'),baseId:operating(s).id,facilityId:suite.id,ids:[...ids],block:1,due:s.turn+1,active:true,intensive:true});members.forEach(m=>{m.status='Training';m.intensiveTurn=s.turn;});log(s,'Intensive training funded',`${members.length} trainees, ${cost} credits, ${v.xp} XP each next Upkeep. Available next turn automatically; no continuation multiplier. Three-turn individual cooldown.`,'good');}
function extractionContingency(s,cid,ids,leads,oid,leader=null){const v=V.advanced_actions.contingency,o=officer(s,oid),k=(o.actorUuid?o.skillRanks?.Medicine>0:!!o.skills.Medicine)?'Medicine':'Survival';advancedOfficer(s,oid,'field',k,v.level,v.actions);const c=offer(s,cid);if(c.status!=='Accepted'||c.contingency||s.contingencyTurn===s.turn)error('One extraction contingency per guild turn and per accepted undeployed job.');const q=quote(s,c,ids,leads,leader),cost=5*Math.ceil(q.pay*v.wage_share/5);spend(s,oid,'Establish an Extraction Contingency',v.actions,cost);const d=rollAdmin(s,oid,'Extraction Contingency',k);s.contingencyTurn=s.turn;c.contingency={charges:v.charges[d],expires:s.turn+1,lock:{ids:[...ids],leads:[...leads],leader}};log(s,'Extraction contingency',`${names[d]}: ${v.charges[d]} protection charge(s), ${cost} funded. Missing-to-Recovering first, then half one repair bill. No success or payout guarantee.`,d>=2?'good':'note');}
function applyContingency(s,j){let charges=j.quote.contingency?.charges||0;if(!charges)return;let used=0;for(const c of [...j.result.complications].sort((a,b)=>(a.type==='missing'?0:a.type==='repairs'?1:2)-(b.type==='missing'?0:b.type==='repairs'?1:2))){if(!charges)break;if(c.type==='missing'){c.type='injury';c.recovery=c.recovery||((j.quote.contractRules.severity||1)*(c.degree===0?2:1));c.text=merc(s,c.lead).name+' extracted by contingency: '+c.recovery+' recovery turn(s), rather than Missing.';}else if(c.type==='repairs'){c.amount=Math.ceil(c.amount/2);c.text='Contingency limits transport damage: '+c.amount+' repair credits.';}else continue;charges--;used++;}j.result.contingencyUsed=used;if(used)log(s,'Contingency activated',j.contract.name+': '+used+' protection charge(s) used. Printed completion and payout unchanged.','good');}

function operativeCapacity(s){return (s.reputation>=80?15:s.reputation>=50?12:s.reputation>=20?9:6)+(s.capacityBonus||0);}
function rosterCount(s){return s.mercs.filter(m=>!['Candidate','Expired','Inactive','Dead','Released'].includes(m.status)).length;}
function releaseOperative(s,mid){if(s.phase!=='activity')error('Release personnel during Activity.');const m=merc(s,mid);if(!['Available','Onboarding','Recovering'].includes(m.status))error('Release an Available, Onboarding or Recovering operative; finish other commitments first.');if(s.cohorts.some(c=>c.active&&c.ids.includes(mid)))error('Finish that operative’s training commitment first.');if(m.dispatchedTurn===s.turn)error('Settle that operative’s mission and pay before release.');m.status='Released';m.releasedTurn=s.turn;log(s,'Operative released',m.name+': recruitment space opens; paid retainers are not refunded and outstanding obligations remain. Routine administration, no Guild Action.');}
